function missingSeriesCard(entry,anchor){const cover={...anchor,title:entry.title},kind=entry.kind||'',label=kind.includes('prequel')?'Prequel companion':kind.includes('novella')?'Novella'+(entry.volume!==null?' · '+entry.volume:''):entry.volume!==null?'Book '+entry.volume:'Series companion';return `<article class="book-card locked-book"><div class="locked-jacket">${jacket(cover)}<span class="lock-seal" aria-hidden="true">♧</span><span class="locked-ribbon">NOT ON YOUR SHELF</span></div><h3>${escape(entry.title)}</h3><p class="book-author">${escape(anchor.author)}</p><p class="book-meta">${escape(label)}</p><a class="evidence-link" href="${escape(entry.source)}" target="_blank" rel="noopener noreferrer">Meet this chapter ↗</a></article>`;}
