function currentPool(){if($('random-mode')?.value==='surprise')return recommendations(profile,emptyCriteria(),{includeRead:false}).filter(r=>r.exact).map(r=>r.book);if(draftDirty||onlineState==='loading'||researchState==='working')return [];if(researchState==='ready')return researchRows.map(r=>r.book);if(resultMode==='description'&&descriptionResult)return descriptionResult.rows.filter(x=>x.exact).map(x=>x.book);return recommendations(profile,criteria,{includeRead:false}).filter(x=>x.exact&&(onlineState!=='ready'||onlineIds.has(x.book.id))).map(x=>x.book);}

function updatePool(){const pool=currentPool(),surprise=$('random-mode')?.value==='surprise',blocked=draftDirty&&!surprise;$('pool-label').textContent=blocked?'Apply your edited craving before drawing.':`${pool.length} eligible ${pool.length===1?'book':'books'} · ${surprise?'your whole library':searchActive?(resultMode==='description'?'your described feeling':'your applied filters'):'your library, with no craving applied'}`;$('random-pick').disabled=!pool.length||blocked;if($('random-help'))$('random-help').textContent=surprise?'A surprise from across your library.':'A surprise within your current craving.';}


